fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    let mut best: Option<Vec<char>> = None;
    let mut best_len: usize = 0;

    for s in strings {
        let len = s.len();
        // If we don't have a best yet, or this string is longer than the current best,
        // pick it as the new best.
        if best.is_none() || len > best_len {
            best_len = len;
            best = Some(s);
        }
    }

    best
}

#[cfg(test)]
mod tests {
    use super::longest;

    #[test]
    fn test_empty() {
        let v: Vec<Vec<char>> = vec![];
        assert_eq!(longest(v), None);
    }

    #[test]
    fn test_single() {
        let v = vec![vec!['a', 'b', 'c']];
        assert_eq!(longest(v), Some(vec!['a', 'b', 'c']));
    }

    #[test]
    fn test_multiple() {
        let v = vec![
            vec!['h', 'i'],
            vec!['t', 'h', 'e', 'r', 'e'],
            vec!['!'],
            vec!['r', 'u', 's', 't', '!', '!'],
            vec!['l', 'o', 'n', 'g', 'e', 's', 't'],
            vec!['s', 'h', 'o', 'r', 't'],
        ];
        // "longest" has length 7, which is the maximum,
        // and it's the first of that maximum length.
        assert_eq!(longest(v), Some("longest".chars().collect()));
    }

    #[test]
    fn test_ties() {
        let v = vec![
            vec!['1', '2', '3'],
            vec!['a', 'b', 'c'],
            vec!['x', 'y', 'z'],
        ];
        // All have length 3; should pick the first one.
        assert_eq!(longest(v), Some(vec!['1', '2', '3']));
    }
}